import React from 'react';
import { Sparkles, Gem, Flame, Trophy, BarChart3, Award, LogOut, Home } from 'lucide-react';
import { baseStyles, FONT_DISPLAY } from '../styles/global';

export function Header({ user, stats, onHome, onDashboard, onBadges, onLogout }) {
  const styles = baseStyles;

  return (
    <header style={styles.header}>
      <div style={styles.headerInner}>
        <button onClick={onHome} style={styles.logo}>
          <div style={styles.logoIcon}>
            <Sparkles size={22} strokeWidth={2.5} />
          </div>
          <div>
            <div style={styles.logoText}>LearnQuest</div>
            <div style={styles.logoTag}>Learn. Practice. Master.</div>
          </div>
        </button>

        <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap' }}>
          <StatChip icon={<Gem size={16} />} value={stats.points} label="pts" color="#9B5DE5" />
          <StatChip icon={<Flame size={16} />} value={stats.streak} label="day streak" color="#FB5607" />
          <StatChip icon={<Trophy size={16} />} value={stats.earnedBadges.length} label="badges" color="#FFB627" />
        </div>

        <div style={{ display: 'flex', gap: 8, alignItems: 'center' }}>
          <button onClick={onDashboard} style={styles.iconBtn} title="Dashboard"><BarChart3 size={18} /></button>
          <button onClick={onBadges} style={styles.iconBtn} title="Badges"><Award size={18} /></button>
          <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
            <div style={{ width: 32, height: 32, borderRadius: 8, background: '#9B5DE5', display: 'flex', alignItems: 'center', justifyContent: 'center', color: 'white', fontWeight: 700 }}>
              {(user?.name || 'L')[0].toUpperCase()}
            </div>
            <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'flex-start', fontSize: 13 }}>
              <span style={{ fontWeight: 700 }}>{user?.name}</span>
              <span style={{ fontSize: 11, color: '#6B7280', textTransform: 'capitalize' }}>{user?.role}</span>
            </div>
          </div>
          <button onClick={onLogout} style={styles.iconBtn} title="Log out"><LogOut size={16} /></button>
        </div>
      </div>
    </header>
  );
}

function StatChip({ icon, value, label, color }) {
  return (
    <div style={{ display: 'flex', alignItems: 'center', gap: 8, padding: '8px 12px', borderRadius: 8, border: `2px solid ${color}`, color }}>
      <span style={{ display: 'inline-flex', alignItems: 'center' }}>{icon}</span>
      <strong style={{ fontSize: 13 }}>{value}</strong>
      <span style={{ fontSize: 11, color: '#6B7280', fontWeight: 500 }}>{label}</span>
    </div>
  );
}

export function Footer() {
  const styles = baseStyles;
  return (
    <footer style={styles.footer}>
      <div style={{ display: 'flex', gap: 12, alignItems: 'center' }}>
        <Sparkles size={16} color="#9B5DE5" />
        <span style={{ fontSize: 13, color: '#6B7280' }}>
          LearnQuest · Built for curious minds, Pre-K to Grade 12
        </span>
      </div>
    </footer>
  );
}

export function BackBtn({ onClick, label }) {
  return (
    <button onClick={onClick} style={{ ...baseStyles.secondaryBtn, marginBottom: 24 }}>
      {'← '} {label}
    </button>
  );
}

export function SectionHeader({ title, subtitle, icon }) {
  return (
    <div style={{ marginBottom: 24 }}>
      <div style={{ display: 'flex', alignItems: 'center', gap: 10, marginBottom: 8 }}>
        {icon}
        <h2 style={{ fontFamily: FONT_DISPLAY, fontSize: 28, fontWeight: 800, color: '#1F2937', margin: 0 }}>{title}</h2>
      </div>
      <p style={{ fontSize: 14, color: '#6B7280', margin: 0 }}>{subtitle}</p>
    </div>
  );
}
